package com.hienlh.ppm.terminal

import android.content.Context
import android.graphics.Typeface
import android.graphics.fonts.Font
import android.graphics.fonts.FontFamily
import android.graphics.fonts.FontStyle
import android.os.Build
import android.util.Log
import androidx.annotation.RequiresApi
import com.hienlh.ppm.design.R as DesignR
import java.io.IOException

/**
 * The bundled part of web's TERMINAL_FONT_FAMILY: Nerd Symbols before Monaspace Argon,
 * then system monospace. Android cannot resolve the user's desktop-installed Meslo fonts.
 * The 14 symbol subsets are generated by `android/scripts/build-terminal-fonts.py`.
 *
 * API 26–28 has no public custom fallback chain: it gets the bundled Monaspace with system
 * fallback, so ordinary terminal text works but private-use Nerd icons may be missing.
 * Termlib 0.3.13 synthesizes bold/italic in its paint from this regular face.
 */
object TerminalFonts {
    @Volatile private var cached: Typeface? = null

    /** Load once across terminal tabs, retaining no Context or Activity. */
    fun typeface(context: Context): Typeface = cached ?: synchronized(this) {
        cached ?: load(context).also { cached = it }
    }

    private fun load(context: Context): Typeface {
        if (Build.VERSION.SDK_INT >= 29) {
            try {
                return FallbackApi29.load(context)
            } catch (error: IOException) {
                Log.w("TerminalFonts", "Terminal font assets unavailable; using Monaspace", error)
            } catch (error: RuntimeException) {
                Log.w("TerminalFonts", "Terminal font chain unavailable; using Monaspace", error)
            }
        }
        return try {
            context.resources.getFont(DesignR.font.monaspace_argon_regular)
        } catch (error: RuntimeException) {
            Log.w("TerminalFonts", "Monaspace unavailable; using system monospace", error)
            Typeface.MONOSPACE
        }
    }

    @RequiresApi(29)
    private object FallbackApi29 {
        // Reverse @font-face order, as Chrome tries them. Every subset has a disjoint cmap.
        private val subsets = listOf(
            "material", "octicons", "font-logos", "font-awesome-legacy", "font-awesome",
            "codicons", "devicons", "seti", "weather", "font-awesome-ext", "powerline",
            "pomicons", "misc", "iec-power",
        )

        fun load(context: Context): Typeface {
            val symbols = subsets.map { subset ->
                val font = Font.Builder(context.assets, "fonts/terminal/nerd-symbols-$subset.ttf")
                    .setWeight(400).setSlant(FontStyle.FONT_SLANT_UPRIGHT).build()
                FontFamily.Builder(font).build()
            }
            val mono = FontFamily.Builder(
                Font.Builder(context.resources, DesignR.font.monaspace_argon_regular).build(),
            ).build()
            return Typeface.CustomFallbackBuilder(symbols.first())
                .apply { symbols.drop(1).forEach { addCustomFallback(it) } }
                .addCustomFallback(mono)
                .setSystemFallback("monospace")
                .setStyle(FontStyle(400, FontStyle.FONT_SLANT_UPRIGHT))
                .build()
        }
    }
}
